import os,json,pathlib,subprocess,sys
repo=pathlib.Path.cwd();r=pathlib.Path(__file__).resolve().parent;plan=json.loads((r/'benchmark-plan.json').read_text());config=plan['configuration']
for variant in ['baseline','candidate']:
 env={**os.environ,'PYTHONPATH':str(r/variant),'OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1','OPENBLAS_NUM_THREADS':'1','VECLIB_MAXIMUM_THREADS':'1'}
 for dtype in config['dtype']:
  target=r/f'memory-{variant}-{dtype}.json'
  subprocess.run([sys.executable,str(r/'benchmarks/bench_graph_memory.py'),'--dtype',dtype,'--output',str(target)],env=env,stdout=subprocess.DEVNULL,check=True)
 print('Memory',variant,flush=True)
extra=sum((['--case',name] for name in config['core_cases']),[])
for dtype in config['dtype']:
 for index,variant in enumerate(config['order']):
  env={**os.environ,'PYTHONPATH':str(r/variant),'OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1','OPENBLAS_NUM_THREADS':'1','VECLIB_MAXIMUM_THREADS':'1'}
  for suite,iterations in [('runtime',120),('tensor_hooks',1200)]:
   target=r/f'cpu-{suite}-{index}-{variant}-{dtype}.json'
   args=[sys.executable,str(r/'benchmarks/bench_cpu.py'),'--benchmark',suite,'--threads','1','--repeat','11','--iterations',str(iterations),'--dtype',dtype,'--output',str(target)]
   if suite=='runtime':args+=extra
   subprocess.run(args,env=env,stdout=subprocess.DEVNULL,check=True)
   report=json.loads(target.read_text());assert pathlib.Path(report['implementation']).is_relative_to(r/variant);assert report['source_hashes']==plan['sources'][variant];assert report['cpu_controls']['accelerate']['after']==1
  print('CPU',index,variant,dtype,flush=True)
 for variant in ['baseline','candidate']:
  for suite,iterations in [('runtime',120),('tensor_hooks',1200)]:
   args=['/opt/homebrew/bin/node',str(r/'benchmarks/bench_wasm.mjs'),'--benchmark',suite,'--source',str(r/variant/'paperleet_torch'),'--runtime',str(repo/'web/node_modules/pyodide'),'--cache',str(repo/'web/public/browser-runtime/pyodide-0.29.4'),'--repeat','11','--iterations',str(iterations),'--dtype',dtype,'--output',str(r/f'node-{suite}-{variant}-{dtype}.json')]
   if suite=='runtime':args+=extra
   subprocess.run(args,stdout=subprocess.DEVNULL,check=True)
   assert json.loads((r/f'node-{suite}-{variant}-{dtype}.json').read_text())['source_hashes']==plan['sources'][variant]
  print('Node WASM',variant,dtype,flush=True)
subprocess.run(['/opt/homebrew/bin/node',str(r/'browser-bench/run.mjs')],check=True)
print('All frozen profiling terminal success',flush=True)

