import fs from 'node:fs';
import assert from 'node:assert/strict';
import {chromium} from '/Users/david/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright/index.mjs';
const plan=JSON.parse(fs.readFileSync(new URL('../benchmark-plan.json',import.meta.url)));
const report={isolation:'fresh Chrome process and Worker per sample',order:['baseline','candidate','prototype','prototype','candidate','baseline'],results:{}};
for(const dtype of ['float32','float64']){
 report.results[dtype]=[];
 for(const variant of report.order){
  const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});
  try{
   report.browser=browser.version();
   const page=await browser.newPage();await page.goto('http://127.0.0.1:8766/torch-iteration-10/browser-bench/');
   const result=await page.evaluate(options=>new Promise((resolve,reject)=>{
    const worker=new Worker('./worker.mjs',{type:'module'});
    const timer=setTimeout(()=>{worker.terminate();reject(new Error('Tensor hooks benchmark timeout'));},180000);
    worker.onmessage=({data})=>{clearTimeout(timer);worker.terminate();resolve(data);};
    worker.onerror=event=>{clearTimeout(timer);worker.terminate();reject(new Error(event.message));};worker.postMessage(options);
   }),{variant,dtype});
   assert(!result.error,JSON.stringify(result));assert.deepEqual(result.source_hashes,plan.sources[variant]);report.results[dtype].push(result);
   fs.writeFileSync(new URL('results.json',import.meta.url),JSON.stringify(report,null,2));
   console.log('Chrome process Tensor hooks',dtype,variant,result.core.library_version);
  }finally{await browser.close();}
 }
}

